"""Find the stretches of opening hours that nobody covers."""

import hourglass.errors
import hourglass.merging
import hourglass.models
import hourglass.parsing


def find_gaps(worked, opening):
    """One label such as 'gap 12:00-13:00 (60 min)' per uncovered stretch.

    Raises ProjectError when a worked span falls outside opening hours.
    """
    worked = list(worked)
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise hourglass.errors.ProjectError(
                "span {} is outside opening hours {}".format(
                    hourglass.parsing.format_span(span),
                    hourglass.parsing.format_span(opening),
                )
            )

    labels = []
    cursor = opening.start
    for span in hourglass.merging.merge_spans(worked):
        if span.start > cursor:
            labels.append(_label(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        labels.append(_label(cursor, opening.end))
    return labels


def _label(start, end):
    return "gap {} ({} min)".format(
        hourglass.parsing.format_span(hourglass.models.Span(start, end)),
        end - start,
    )
EOF
cat > tests/test_gaps.py <<'EOF'
import unittest

import hourglass.errors
import hourglass.gaps
import hourglass.models


def span(start, end):
    return hourglass.models.Span(start * 60, end * 60)


class GapTests(unittest.TestCase):
    def test_when_middle_is_uncovered_gap_is_reported(self):
        result = hourglass.gaps.find_gaps(
            [span(9, 12), span(13, 17)], span(9, 17)
        )
        self.assertEqual(result, ["gap 12:00-13:00 (60 min)"])

    def test_when_edges_are_uncovered_gaps_are_reported(self):
        result = hourglass.gaps.find_gaps([span(10, 11)], span(9, 12))
        self.assertEqual(
            result, ["gap 09:00-10:00 (60 min)", "gap 11:00-12:00 (60 min)"]
        )

    def test_when_fully_covered_there_are_no_gaps(self):
        result = hourglass.gaps.find_gaps(
            [span(9, 13), span(12, 17)], span(9, 17)
        )
        self.assertEqual(result, [])

    def test_when_nobody_works_whole_day_is_a_gap(self):
        result = hourglass.gaps.find_gaps([], span(9, 10))
        self.assertEqual(result, ["gap 09:00-10:00 (60 min)"])

    def test_when_span_is_outside_opening_hours_it_raises(self):
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.gaps.find_gaps([span(8, 10)], span(9, 17))
